package io.tenvyr.control.authority;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import java.sql.Connection;
import java.util.*;

/** Append-only ledger. The account chain is locked before every availability-changing operation. */
public final class BudgetLedgerService {
    private final Db db;
    public BudgetLedgerService(Db db){this.db=db;}
    private <T>T tx(Connection c,Db.Work<T> work){return c==null?db.transaction(work):Db.on(c).transaction(work);}
    public ObjectNode createAccount(JsonNode input,Connection c){String type=BudgetDomain.bounded(input.get("scopeType"),32,"scopeType"),scope=BudgetDomain.bounded(input.get("scopeId"),255,"scopeId");ObjectNode ceilings=BudgetDomain.ceilings(input.get("ceilings"));JsonNode soft=input.hasNonNull("softCeilings")?BudgetDomain.ceilings(input.get("softCeilings")):NullNode.instance;return tx(c,t->{String parent=Json.text(input,"parentAccountId");if(parent!=null){ObjectNode direct=chain(t,parent).stream().filter(a->parent.equals(Json.text(a,"id"))).findFirst().orElseThrow();subset(ceilings,direct);if(!soft.isNull())subset(soft,direct);}ObjectNode row=t.one("INSERT INTO budget_accounts (\"scopeType\",\"scopeId\",\"parentAccountId\",ceilings,\"softCeilings\") VALUES (?,?,?::uuid,?,?) ON CONFLICT (\"scopeType\",\"scopeId\") DO NOTHING RETURNING *",type,scope,parent,ceilings,soft);if(row==null)throw error("SCOPE_ALREADY_EXISTS","Budget scope already exists");return row;});}
    public ObjectNode ensureExecutionAccount(Connection c,String executionId,JsonNode pipelineBudget,JsonNode stepBudget){return tx(c,t->{ObjectNode row=t.one("SELECT * FROM budget_accounts WHERE \"scopeType\"='execution' AND \"scopeId\"=?",executionId);if(row!=null)return row;JsonNode ceilings=pipelineBudget!=null&&!pipelineBudget.isNull()?pipelineBudget.path("ceilings"):stepBudget;ceilings=BudgetDomain.ceilings(ceilings);String parentId=null;if(pipelineBudget!=null&&pipelineBudget.hasNonNull("parent")){JsonNode p=pipelineBudget.get("parent");ObjectNode parent=t.one("SELECT * FROM budget_accounts WHERE \"scopeType\"=? AND \"scopeId\"=?",p.get("scopeType"),p.get("scopeId"));if(parent==null)throw error("ACCOUNT_NOT_FOUND","Operator-managed parent budget does not exist");subset(ceilings,parent);parentId=Json.text(parent,"id");chain(t,parentId);}t.execute("INSERT INTO budget_accounts (\"scopeType\",\"scopeId\",\"parentAccountId\",ceilings,\"softCeilings\") VALUES ('execution',?,?::uuid,?,NULL) ON CONFLICT (\"scopeType\",\"scopeId\") DO NOTHING",executionId,parentId,ceilings);return t.one("SELECT * FROM budget_accounts WHERE \"scopeType\"='execution' AND \"scopeId\"=?",executionId);});}
    public ObjectNode reserve(JsonNode input,Connection c){String dimension=BudgetDomain.dimension(Json.text(input,"dimension"));long amount=BudgetDomain.amount(dimension,input.get("amount"));String key=BudgetDomain.bounded(input.get("idempotencyKey"),255,"idempotencyKey"),account=Json.text(input,"accountId");String ref=input.hasNonNull("actionRef")?BudgetDomain.bounded(input.get("actionRef"),255,"actionRef"):null;String source=BudgetDomain.source(input.get("source"));JsonNode confidence=BudgetDomain.confidence(input.get("confidence")),evidence=BudgetDomain.evidence(input.get("evidence"));
        return tx(c,t->{List<ObjectNode> chain=chain(t,account);ObjectNode existing=t.one("SELECT * FROM budget_reservations WHERE \"idempotencyKey\"=?",key);if(existing!=null)return replay(existing,account,dimension,amount);for(ObjectNode a:chain)if(available(t,a,dimension)<amount)throw error("INSUFFICIENT_BUDGET","Insufficient "+dimension+" budget");ObjectNode row=t.one("INSERT INTO budget_reservations (\"accountId\",\"idempotencyKey\",dimension,amount,status,\"actionRef\") VALUES (?::uuid,?,?,?,'ACTIVE',?) ON CONFLICT (\"idempotencyKey\") DO NOTHING RETURNING *",account,key,dimension,amount,ref);if(row==null)return replay(t.one("SELECT * FROM budget_reservations WHERE \"idempotencyKey\"=?",key),account,dimension,amount);writeChain(t,chain,row,"reserve",amount,source,confidence,key,evidence);return row;});
    }
    public ObjectNode commit(JsonNode input,Connection c){return tx(c,t->{ObjectNode r=reservationLocked(t,Json.text(input,"reservationId"));if(!"ACTIVE".equals(Json.text(r,"status")))throw error("RESERVATION_NOT_ACTIVE","Reservation is not active");String d=Json.text(r,"dimension");long amount=BudgetDomain.amount(d,input.get("amount"));if(amount>Json.longValue(r,"amount",0))throw error("RESERVATION_AMOUNT_EXCEEDED","Commit exceeds reservation");t.insert("budget_ledger_entries",Json.object("accountId",r.get("accountId"),"reservationId",r.get("id"),"operation","commit","dimension",d,"amount",amount,"source",BudgetDomain.source(input.get("source")),"confidence",BudgetDomain.confidence(input.get("confidence")),"idempotencyKey",Json.text(r,"idempotencyKey")+":commit","evidence",BudgetDomain.evidence(input.get("evidence"))));return t.update("budget_reservations",Json.text(r,"id"),Json.object("status","COMMITTED"));});}
    public ObjectNode release(JsonNode input,Connection c){return tx(c,t->{ObjectNode r=reservationLocked(t,Json.text(input,"reservationId"));if(!List.of("ACTIVE","COMMITTED").contains(Json.text(r,"status")))throw error("RESERVATION_NOT_ACTIVE","Reservation cannot release");long amount=BudgetDomain.amount(Json.text(r,"dimension"),input.get("amount"));ObjectNode total=t.one("SELECT COALESCE(SUM(amount),0) total FROM budget_ledger_entries WHERE \"reservationId\"=?::uuid AND operation='commit'",r.get("id"));if(amount>Json.longValue(r,"amount",0)-Json.longValue(total,"total",0))throw error("RESERVATION_AMOUNT_EXCEEDED","Release would erase actual work");JsonNode evidence=input.hasNonNull("reason")?BudgetDomain.evidence(Json.object("reason",input.get("reason").asText())):NullNode.instance;writeChain(t,chain(t,Json.text(r,"accountId")),r,"release",amount,BudgetDomain.source(input.get("source")),BudgetDomain.confidence(input.get("confidence")),Json.text(r,"idempotencyKey")+":release",evidence);return t.update("budget_reservations",Json.text(r,"id"),Json.object("status","RELEASED"));});}
    public ObjectNode adjust(JsonNode input,Connection c){String d=BudgetDomain.dimension(Json.text(input,"dimension"));long delta=BudgetDomain.delta(d,input.get("delta"));String reason=BudgetDomain.bounded(input.get("reason"),255,"reason"),account=Json.text(input,"accountId");return tx(c,t->{List<ObjectNode> chain=chain(t,account);for(ObjectNode a:chain){long signed=account.equals(Json.text(a,"id"))?delta:-delta;long value=available(t,a,d);if(signed<0&&value< -signed)throw error("AVAILABILITY_NEGATIVE","Adjustment exceeds available grant");if(signed>0&&value>BudgetDomain.MAX-signed)throw error("AMOUNT_OVERFLOW","Adjustment overflows grant");}ObjectNode first=null;for(ObjectNode a:chain){ObjectNode row=t.insert("budget_ledger_entries",Json.object("accountId",a.get("id"),"reservationId",null,"operation","adjust","dimension",d,"amount",Math.abs(delta),"delta",account.equals(Json.text(a,"id"))?delta:-delta,"source","actual","idempotencyKey",null,"evidence",Json.object("reason",reason)));if(first==null)first=row;}return first;});}
    public ObjectNode projection(String accountId){return db.transaction(t->{ObjectNode a=t.one("SELECT * FROM budget_accounts WHERE id=?::uuid",accountId);if(a==null)throw error("ACCOUNT_NOT_FOUND","Budget account not found");return Json.object("account",a,"available",BudgetDomain.projectAll(a.get("ceilings"),facts(t,accountId)));});}
    public ObjectNode reservation(String id){return db.one("SELECT * FROM budget_reservations WHERE id=?::uuid",id);}
    public void reserveForAttempt(Connection c,JsonNode input){JsonNode b=BudgetDomain.ceilings(input.get("budget"));for(String d:Json.keys(b))reserve(Json.object("accountId",input.get("accountId"),"dimension",d,"amount",b.get(d),"idempotencyKey",BudgetDomain.reservationKey(Json.text(input,"executionId"),Json.text(input,"logicalStepId"),Json.integer(input,"attemptNumber",1),d),"actionRef",input.get("invocationId"),"source","unknown"),c);}
    public void reconcileTerminal(Connection c,String ref,JsonNode usage){ArrayNode observations=BudgetDomain.usage(usage);tx(c,t->{for(ObjectNode r:t.query("SELECT * FROM budget_reservations WHERE \"actionRef\"=? ORDER BY id",ref)){if(!"ACTIVE".equals(Json.text(r,"status")))continue;JsonNode observation=null;for(JsonNode o:observations)if(o.path("dimension").equals(r.get("dimension")))observation=o;if(observation==null)continue;long reserved=Json.longValue(r,"amount",0),amount=Math.min(reserved,Json.longValue(observation,"amount",0));if(amount>0)commit(Json.object("reservationId",r.get("id"),"amount",amount,"source",observation.get("source"),"evidence",Json.object("actionRef",ref)),t.connection());if(reserved>amount)release(Json.object("reservationId",r.get("id"),"amount",reserved-amount,"reason","unused reservation after terminal result"),t.connection());}return null;});}
    public void releaseForAction(Connection c,String ref,String reason){tx(c,t->{for(ObjectNode r:t.query("SELECT * FROM budget_reservations WHERE \"actionRef\"=? ORDER BY id",ref)){if(!"ACTIVE".equals(Json.text(r,"status")))continue;release(Json.object("reservationId",r.get("id"),"amount",r.get("amount"),"reason",reason),t.connection());}return null;});}
    private List<ObjectNode> chain(Db t,String id){List<ObjectNode> chain=new ArrayList<>();Set<String> seen=new HashSet<>();while(id!=null){if(!seen.add(id)||seen.size()>16)throw error("CHAIN_TOO_DEEP","Account hierarchy exceeds bounds or cycles");ObjectNode a=t.one("SELECT * FROM budget_accounts WHERE id=?::uuid FOR UPDATE",id);if(a==null)throw error("ACCOUNT_NOT_FOUND","Budget ancestor not found");chain.add(a);id=Json.text(a,"parentAccountId");}chain.sort(Comparator.comparing(a->Json.text(a,"id")));return chain;}
    private List<ObjectNode> facts(Db t,String account){List<ObjectNode> rows=t.query("SELECT * FROM budget_ledger_entries WHERE \"accountId\"=?::uuid ORDER BY \"createdAt\",id LIMIT 10001",account);if(rows.size()>10000)throw error("PROJECTION_TOO_LARGE","Budget projection exceeds bounded scan");return rows;}
    private long available(Db t,ObjectNode a,String d){return BudgetDomain.available(a.get("ceilings"),facts(t,Json.text(a,"id")),d);}
    private ObjectNode reservationLocked(Db t,String id){ObjectNode r=t.one("SELECT * FROM budget_reservations WHERE id=?::uuid FOR UPDATE",id);if(r==null)throw error("RESERVATION_NOT_ACTIVE","Reservation not found");return r;}
    private void writeChain(Db t,List<ObjectNode> chain,JsonNode r,String op,long amount,String source,JsonNode confidence,String key,JsonNode evidence){for(ObjectNode a:chain)t.insert("budget_ledger_entries",Json.object("accountId",a.get("id"),"reservationId",r.get("id"),"operation",op,"dimension",r.get("dimension"),"amount",amount,"source",source,"confidence",confidence,"idempotencyKey",key+":"+Json.text(a,"id"),"evidence",evidence));}
    private ObjectNode replay(ObjectNode r,String account,String d,long amount){if(r!=null&&account.equals(Json.text(r,"accountId"))&&d.equals(Json.text(r,"dimension"))&&amount==Json.longValue(r,"amount",0))return r;throw error("IDEMPOTENCY_CONFLICT","Reservation identity reused with different request");}
    public static void subset(JsonNode child,JsonNode parent){JsonNode ceilings=parent.path("ceilings");for(String d:Json.keys(child))if(!ceilings.has(d)||child.path(d).longValue()>ceilings.path(d).longValue())throw error("CHILD_CEILING_EXCEEDS_PARENT","Child ceiling exceeds immutable parent grant");}
    private static AuthorityError error(String c,String m){return new AuthorityError(c,m);}
}
